import java.math.BigInteger;

public BigInteger fibonacciModified(int t1, int t2, int n) {
    return term(BigInteger.valueOf(t1), BigInteger.valueOf(t2), n);
}

private BigInteger term(BigInteger t1, BigInteger t2, int i) {
    if (i == 1) return t1;
    if (i == 2) return t2;
    BigInteger prev = term(t1, t2, i - 1);
    BigInteger prevPrev = term(t1, t2, i - 2);
    return prevPrev.add(prev.multiply(prev));
}

