def fibonacciModified(self, t1: int, t2: int, n: int) -> int:
    def term(i: int) -> int:
        if i == 1:
            return t1
        if i == 2:
            return t2
        prev = term(i - 1)
        prev_prev = term(i - 2)
        return prev_prev + prev * prev
    return term(n)

