import java.math.BigInteger;

public BigInteger fibonacciModified(int t1, int t2, int n) {
    BigInteger prevPrev = BigInteger.valueOf(t1);
    BigInteger prev = BigInteger.valueOf(t2);
    for (int i = 3; i <= n; i++) {
        BigInteger cur = prevPrev.add(prev.multiply(prev));
        prevPrev = prev;
        prev = cur;
    }
    return prev;
}

